export function realCutoutPixels(): Uint8ClampedArray {
  // atob rather than Buffer: this module is type-checked against the browser lib alongside the
  // rest of the app, and Buffer does not exist there.
  const binary = atob(CUTOUT_B64);
  const bytes = new Uint8ClampedArray(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
